1	/** Flat fee added to every premium, regardless of the items insured. */
2	const PROCESSING_FEE = 5;
3	
4	/** Base premium of a sword. */
5	const SWORD_BASE_PREMIUM = 100;
6	
7	/** Base premium of an amulet. */
8	const AMULET_BASE_PREMIUM = 60;
9	
10	/** Initial assessment surcharge on a customer's first insurance. */
11	const FIRST_INSURANCE_RATE = 0.1;
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: Step[];
16	};
17	
18	export type Step = {
19	  op: string;
20	  items: Item[];
21	};
22	
23	export type Item = Record<string, unknown>;
24	
25	export type Result = { premium: number };
26	
27	export type ScenarioOutcome = { results: Result[] };
28	
29	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
30	  const items = scenario.steps[0].items;
31	  const policyBase = items.reduce(
32	    (sum, item) =>
33	      sum + (item.type === "amulet" ? AMULET_BASE_PREMIUM : SWORD_BASE_PREMIUM),
34	    0,
35	  );
36	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_RATE;
37	  return {
38	    results: [{ premium: policyBase + firstInsuranceSurcharge + PROCESSING_FEE }],
39	  };
40	};
41

1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: simplest cases ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const scenario = {
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    };
11	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
12	  });
13	  it("a single plain sword → base premium 100 G, plus first insurance 10 G and 5 G fee → 115 G", () => {
14	    const scenario = {
15	      customer: { yearsWithMHPCO: 0 },
16	      steps: [
17	        {
18	          op: "quote",
19	          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
20	        },
21	      ],
22	    };
23	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
24	  });
25	  it("a single plain amulet → base premium 60 G (+10 % first insurance, +5 G fee) → 71 G", () => {
26	    const scenario = {
27	      customer: { yearsWithMHPCO: 0 },
28	      steps: [
29	        {
30	          op: "quote",
31	          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
32	        },
33	      ],
34	    };
35	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
36	  });
37	  it.todo("a single plain staff → base premium 80 G (+10 % first insurance, +5 G fee) → 93 G");
38	  it.todo("a single plain potion → base premium 40 G (+10 % first insurance, +5 G fee) → 49 G");
39	  it.todo("a single rune → base premium 25 G (+10 % first insurance, +5 G fee) → 33 G");
40	  it.todo("a single moonstone → base premium 25 G (+10 % first insurance, +5 G fee) → 33 G");
41	
42	  // --- Component blocks of 3 alike ---
43	  it.todo("2 runes → 50 G base premium");
44	  it.todo("3 runes → 60 G base premium (block applies)");
45	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
46	  it.todo("7 runes → 175 G base premium");
47	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
48	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
49	
50	  // --- Premium modifiers in isolation ---
51	  it.todo("cursed sword adds a 50 % risk surcharge on the item's base premium (100 G → +50 G)");
52	  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies (+30 G)");
53	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
54	  it.todo("cursed sword with exactly enchantment 5 → both surcharges apply (+50 G and +30 G)");
55	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
56	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
57	  it.todo("first insurance carries a 10 % initial assessment surcharge");
58	  it.todo("each contract after the customer's first receives a 15 % discount");
59	  it.todo("a 5 G processing fee is added to every premium");
60	
61	  // --- Modifier scope on multi-item policies ---
62	  it.todo("cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (item-scoped) → 210 G before further modifiers and fee");
63	  it.todo("policy-wide modifiers (loyalty, first insurance, follow-up) apply to the policy base premium, the fee is added at the very end");
64	
65	  // --- Rounding ---
66	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
67	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
68	  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");
69	
70	  // --- Claim: standard reimbursement ---
71	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
72	  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");
73	
74	  // --- Claim: special clauses ---
75	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
76	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
77	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
78	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
79	
80	  // --- Claim: deductible per damage event ---
81	  it.todo("dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)");
82	
83	  // --- Claim: insurance sum and cap ---
84	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
85	  it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
86	  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G (the block discount affects the premium only)");
87	  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
88	
89	  // --- Claim: cap exhaustion across successive claims ---
90	  it.todo("sword insured (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
91	  it.todo("sword insured (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");
92	
93	  // --- Multiple items of the same type ---
94	  it.todo("two swords insured and both damaged → each damage entry gets its own deductible");
95	
96	  // --- Error cases ---
97	  it.todo("quote with an unknown item type (e.g. broomstick) → error, no results");
98	  it.todo("claim referencing an item not part of the policy (amulet damaged, only a sword insured) → error");
99	  it.todo("claim referencing an item with an unknown type → error");
100	  it.todo("claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
101	  it.todo("claim with a damage entry of amount -200 → error");
102	
103	  // --- Integration examples ---
104	  it.todo("newcomer (0 years, no previous contract) with a cursed sword (steel, enchantment 3) → premium 165 G");
105	  it.todo("long-standing customer (3 years), second quote, cursed sword (steel, enchantment 7) → premium 160 G");
106	
107	  // --- CLI ---
108	  it.todo("CLI reads a scenario from stdin and writes {results: [...]} to stdout in step order");
109	  it.todo("CLI exits with a non-zero status code and writes an error description to stderr on an invalid scenario");
110	});
