export const runScenario = (scenario: Scenario): ScenarioOutcome => {
  const items = scenario.steps[0].items;
  const policyBasePremium = items.reduce(
    (sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type as string],
    0,
  );
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
  return {
    results: [
      { premium: policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE },
    ],
  };
};
